P=[[8,9,8,9,6,9,8,7],[9,9,9,8,8,3,9,9]]
def build(subs):
    # subs: set of region copies besides source (1,1); regions rows {0,1}, cols {0,1,2}
    g=[[9]*26 for _ in range(5)]
    for c in range(26): g[2][c]=4
    for r in range(5):
        for c in (8,17): g[r][c]=4
    def place(rr,cc):
        r0=0 if rr==0 else 3
        c0=0 if cc==0 else (9 if cc==1 else 18)
        for i in range(2):
            for j in range(8):
                g[r0+i][c0+j]=P[i][j]
    place(1,1)
    for (rr,cc) in subs: place(rr,cc)
    return g
